  Lemma conv_state_at : forall k d ps n, (0 <= k)%Z -> conv_state (sfx k) = Some (d_ty d, ps, n) ->
    (k + Z.of_nat n <= zlength fmt)%Z /\ (1 <= n)%nat
    /\ nth (n - 1)%nat (sfx k) 0%Z = znth fmt (k + Z.of_nat n - 1)
    /\ skipn n (sfx k) = sfx (k + Z.of_nat n)
    /\ dir_ps d = ps.
Proof.
