Section PrintfCore.
  Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
  Context {St : Type}.
  Variables (Fp B BS X1 N1 X2 N2 : Z) (SINK : (word -> option byte) -> St -> Prop) (TOPOK : Z -> Prop)
            (OUT : list Z -> M St unit) (OUTFP : Z -> Z -> Z -> Z -> Z -> M St Z).
  Hypothesis SFR : sink_frame_stmt Fp B BS X1 N1 X2 N2 SINK.
  Hypothesis SFL : sink_flags_stmt Fp SINK.
  Hypothesis TOK : topok_stmt TOPOK.
  Hypothesis HOUT : out_stmt Fp B BS X1 N1 X2 N2 SINK TOPOK OUT.
  Variables (ra : word) (q : Z) (gp tp : word) (s0e s1e s2e s3e s4e s5e s6e s7e s8e s9e s10e s11e : word)
            (F : bvmap 5 word) (fc0 : bv 32) (m0 : word -> option byte)
            (lo : Z) (canary : word) (A : Z) (fmt : list Z) (AP VA : Z) (slots : list word) (nla nlt : word).
  Hypothesis HF : Forall (fun c => 0 <= c < 256)%Z fmt.
  Hypothesis LO : (lo <= q - PC_DEPTH)%Z.
  Hypothesis GLO : (GLOBALS_TOP <= lo)%Z.
  Hypothesis QHI : (q < 2^63)%Z.
  Hypothesis TQ : TOPOK q.
  Hypothesis FRM0 : frm0 fc0.
  (* [comment removed for export] *)
  Hypothesis HA : (A + zlength fmt <= 2142208)%Z.          (* [comment removed for export] *)
  (* [comment removed for export] *)
  Hypothesis SEP_F : ((2186832 <= Fp /\ Fp + 232 <= 2285568) \/ (AP + 8 <= Fp /\ Fp + 232 <= VA))%Z.
  Hypothesis SEP_B : ((7878496 <= B /\ B + BS <= lo /\ B + BS <= 7884800) \/ (AP + 8 <= B /\ B + BS <= VA))%Z.
  Hypothesis SEP_X1 : (AP + 8 <= X1 /\ X1 + N1 <= VA /\ 0 <= N1)%Z.                 (* [comment removed for export] *)
  Hypothesis SEP_X2 : (7884800 <= X2 /\ X2 + N2 <= lo /\ 0 <= N2 /\ (X2 + N2 <= SHADOW_LO \/ SHADOW_HI <= X2))%Z.   (* [comment removed for export] *)
  Hypothesis HAP : (q <= AP)%Z.
  Hypothesis HVA : (AP + 8 <= VA)%Z.
  Hypothesis A0 : (0 <= A)%Z.
  Hypothesis VAHI : (VA + 8 * zlength slots <= 2^64)%Z.
  Hypothesis BS0 : (0 <= BS)%Z.
  (* [comment removed for export] *)
  Hypothesis RIP : rip_stmt.
  Hypothesis HA0 : aext m0 lo q A fmt B BS X2 N2.

  Notation sfx := (sfx fmt).
  Definition ctx_all : unit :=
    let _ := (ra, q, gp, tp, s0e, s1e, s2e, s3e, s4e, s5e, s6e, s7e, s8e, s9e, s10e, s11e, F, fc0, m0,
              lo, canary, A, fmt, AP, VA, slots, nla, nlt) in tt.

  (* [comment removed for export] *)
  Definition W : list (Z * Z) := [(lo, q); (AP, AP + 8); (Fp, Fp + 232); (B, B + BS); (X1, X1 + N1); (X2, X2 + N2)]%Z.
  Notation qq := (q + -544)%Z.
  Notation SPv := (Z_to_bv 64 (q + -544)).
  Notation FPv := (Z_to_bv 64 Fp).

  Definition Fokd (F1 F2 : bvmap 5 word) : Prop := forall k : reg, bv_unsigned k <> 10%Z -> reg_get F2 k = reg_get F1 k.
  Definition Fok (Ft : bvmap 5 word) : Prop := forall k : reg, bv_unsigned k <> 10%Z -> reg_get Ft k = reg_get F k.
  Lemma Fok_refl : Fok F.
Proof.
ltac2:(KReplay.run1 (kr_t_F_printf_core_common ()) ["PrintfCore"] "h02_Hh11kp;1p;2p;3g005ij10Tg00S?j1:Tg006Nj11Tg006lj12Tg02GXj29Tg011>j18Tg009Jj37Tg00Jgj14Tg03iRj25Tg00>Ej26Tg03j<j13Tg00:B#0R0#:R1#1R2#2g009df0,92%01#837#4%00#0#0#0#0#1#2p,1FR0f1'5'6W0W1%30eo"). Qed.
  Lemma Fok_trans : forall F1 F2, Fok F1 -> (forall k : reg, bv_unsigned k <> 10%Z -> reg_get F2 k = reg_get F1 k) -> Fok F2.
Proof.
ltac2:(KReplay.run1 (kr_t_F_printf_core_common ()) ["PrintfCore"] "h01kh12F1h22F2h32H1h42H2h52Hkh61bp;1p;2p;3p;6g005ij10Tg00S?j1;Tg006Nj13Tg006lj14Tg001ej2:Tg03j<j15Tg02GXj29Tg011>j18Tg009Jj32Tg00Jgj17Tg03iRj21Tg001Gj66Tg00:B#0R0#;R1#3R2%00#0#0#0#0#3#4R0':R3f1R4#5%42R5g009df0R6,92%01#832#7R1f3R2/14f4/14R7520[]0P0f5/14p,1Ff2R8'19206X60P2P4P6O2P7P8P4P6O2E6X51X05%58eW4W3X23W1o"). Qed.

  Definition POST : Z -> St -> machine_state -> Prop :=
    fun r st' ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (Ft : bvmap 5 word) (fc' : bv 32) (apv : word) (m' : word -> option byte),
      ms' = MS (mkR ra (Z_to_bv 64 q) gp tp t0 t1 t2 s0e s1e (Z_to_bv 64 r) a1 a2 a3 a4 a5 a6 a7 s2e s3e s4e s5e s6e s7e s8e s9e s10e s11e t3 t4 t5 t6)
               Ft (ret_pc ra) fc' None m' (seg_rom asegs)
      /\ munch W m0 m' /\ wmono asegs m0 m' /\ mem_inv asegs m'
      /\ frm0 fc' /\ Fok Ft
      /\ stk asegs m' lo q
      /\ SINK m' st'
      /\ ssp_cells m' canary
      /\ rw_cells asegs m' AP [C8 apv]
      /\ (0 <= r <= INT_MAX)%Z.

  (* [comment removed for export] *)
  Definition hi_cells : list cell :=
    [C8 canary; C8 s11e; C8 s10e; C8 s9e; C8 s8e; C8 s7e; C8 s6e; C8 s5e; C8 s4e; C8 s3e; C8 s2e; C8 s1e; C8 s0e; C8 ra].

  (* [comment removed for export] *)
  Definition lo_cells (pfx s2s za pl plp l10n alo ahi : word) (j128 : list byte) : list cell :=
    [C8 pfx; C8 s2s; C8 za; C8 pl; C8 plp; C8 (Z_to_bv 64 18446744072850558157); C8 (Z_to_bv 64 18446744073709486079);
     C8 nla; C8 nlt; C8 (Z_to_bv 64 AP); C8 (Z_to_bv 64 75913); C8 l10n; C8 (Z_to_bv 64 ssp_guard); C8 (Z_to_bv 64 214748364);
     C8 alo; C8 ahi; CB 24 j128].

  (* [comment removed for export] *)
  Definition finv (m : word -> option byte) : Prop :=
    mem_inv asegs m /\ munch W m0 m /\ wmono asegs m0 m
    /\ rw_cells asegs m (q + -112) hi_cells
    /\ stk asegs m lo (q + -544)
    /\ bytes_at asegs m A (zb fmt)
    /\ va_area m VA slots
    /\ ro_cells asegs m got_ssp [C8 (Z_to_bv 64 ssp_guard)] /\ ro_cells asegs m ssp_guard [C8 canary].   (* [comment removed for export] *)
  (* [comment removed for export] *)
  Ltac hush := idtac.
  Ltac seps := idtac.
  Ltac seps_all := idtac.
  (* [comment removed for export] *)
  Ltac zs := hush; zstep; try (fix_litstore; mem_after_store_opt).
  Ltac zst := hush; seps; zstep; try (fix_litstore; mem_after_store_opt); hush.

  Ltac dest_finv H := let MI := fresh "MI" in let MU := fresh "MU" in let WM := fresh "WM" in let FRhi := fresh "FRhi" in
    let ST := fresh "ST" in let BY := fresh "BY" in let VAA := fresh "VAA" in let SSP1 := fresh "SSP1" in let SSP2 := fresh "SSP2" in
    destruct H as (MI & MU & WM & FRhi & ST & BY & VAA & SSP1 & SSP2); unfold W in MU; unfold hi_cells in FRhi;
    unfold got_ssp, ssp_guard in SSP1, SSP2; unfold va_area in VAA;
    unfold PC_DEPTH, GLOBALS_TOP in LO, GLO;
    try (let LT := fresh "LZB" in pose proof (zb_length fmt) as LT;
         lazymatch goal with _ : length (zb fmt) = length fmt, _ : length (zb fmt) = length fmt |- _ => clear LT | _ => idtac end);
    try (let LT := fresh "LU" in pose proof (u64s_length slots) as LT;
         lazymatch goal with _ : length (u64s slots) = _, _ : length (u64s slots) = _ |- _ => clear LT | _ => idtac end);
    unfold zlength in *; hush.
  Ltac hyp :=
    lazymatch goal with
    | |- rw_cells _ ?m ?A ?cs =>
        match goal with H : rw_cells _ ?m' ?A' ?cs' |- _ => constr_eq m' m; constr_eq A' A; unify cs' cs; exact H end
    | |- ?G => match goal with H : ?T |- _ => constr_eq T G; exact H end
    end.
  Ltac mk_finv := unfold finv, W, hi_cells, got_ssp, ssp_guard, va_area;
    split; [hyp|]; split; [hyp|]; split; [hyp|]; split; [hyp|]; split; [first [hyp | hyp_cells] |]; split; [hyp|]; split; [hyp|]; split; hyp.

  (* [comment removed for export] *)
  Ltac at_pc p := lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 ?q0) _ _ _ _) => constr_eq q0 p end.
  Ltac zsto p := repeat (tryif at_pc p then fail else
                   lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 _) _ _ _ _) => zs end).

  Lemma u8_lit : forall c, (0 <= c < 256)%Z -> bv_unsigned (Z_to_bv 8 c) = c.
Proof.
ltac2:(KReplay.run1 (kr_t_F_printf_core_common ()) ["PrintfCore"] "h02Hah14__x1h22Hch37__arithh44__ffh56__sat3h66__sat4h76__sat5h86__sat6h96__sat7h:6__sat8h;8__varmaph<5__with=1ch>1zp;1p;2p;3p;4p;8p;6p;7p103k@p6061002R0p101XXp4p710p8P0p103lEp4p710p8g005ij11Tg011>j13Tg00A4j22Tg00APj2<Tg006Nj1RTg03mBj2LTg009Jj3:Tg03mhj1CTg024]j25Tg00S?j14Tg025Zj29Tg026Bj3;Tg00Cnj1VTg005Ij1UTg00DNj2TTg00Dlj1QTg00EJj1NTg00FXj26Tg00F5j2KTg00G;j48Tg00Gfj1ETg027Gj3DTg00WHj8FTg00HHj2GTg00>Ej2HTg00Hjj2BTg00IVj3ITg00J5j4JTg027jj3ATg007Oj2@Tg02GXj2MTg03nFj2?Tg001Gj6OTg00?]j2PTg00U\j7>Tg00Vdj7STg00Y6R0f0R1'Pp=0f1R2g00YTR3g00Z3R4P4g00ZSR5P1g00[3F>p=7f2R6P3P4P4P5P2P1FSp==g009dR7%01g00:BR8#1R9#1#1R:#1#1#1R;#1#1#3R<,21'<R=P7%R:R>/L2R?A:716X>7%39R9%C>'5R@%48#4#4#4#4#3RA,991209RB%0A159ARC,20[[%09RDg01UTREA;9A2UW0%0C\E^0D%3:R:,99%0:159:RC,20[\BA;9:2VEX0D%0C\E^0D%3;R;,99%0;159;R:,20[\BA;9;2VEX0D%0:\E^0Dg00]BRD#V%UD1T72%Q7%N7RDP3P4P4P5P71670g00^U1K78R8C8,7DR3P7P8g00]nRE167<C8,7D5=D%E4P7P8PE1679=D7>C8,7D9=D3GF1GD5P1P6g00\bRDg00_<R5'H1B16=:D5dAI702CJb4b;b<X17%02R0122C'<\=^17P1f8f7O2b3b5b6b7b8b9b:122@,<0e5A2A:7?2e1@>2,M>1?>2EOW2W=o"). Qed.
  Lemma fmt_rng : forall i, (0 <= i < zlength fmt)%Z -> (0 <= znth fmt i < 256)%Z.
Proof.
