  (* [comment removed for export] *)
  Definition memset_postq (ra' : word) (Ft : bvmap 5 word) (fc : bv 32) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
      (D C N : Z) (m : word -> option byte) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1' a2' a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra' SPv gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 D) a1' a2' a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               Ft (ret_pc ra') fc None m' (seg_rom asegs)
      /\ munch [(D, D + N); (q + -544 - 2224, q + -544)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
      /\ rw_cells asegs m' D [CB (Z.to_nat N) (repeat (Z_to_bv 8 (C mod 256)) (Z.to_nat N))]
      /\ stk asegs m' lo (q + -544).
  Lemma memset_callq : forall ra' t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (Ft : bvmap 5 word) fc (m : word -> option byte) (D C N : Z) (junk : list byte),
    rw_cells asegs m D [CB (Z.to_nat N) junk] ->
    mem_inv asegs m ->
    (0 <= D)%Z -> (0 <= N < 2^64)%Z -> (D + N <= 2^64)%Z -> (0 <= C < 2^64)%Z ->
    stk asegs m lo (q + -544) -> munch W m0 m -> wmono asegs m0 m -> (q + -544 <= D)%Z -> (D + N <= q)%Z -> (0 < N)%Z ->
    evt asegs (memset_postq ra' Ft fc s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 D C N m)
      (MS (mkR ra' SPv gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 D) (Z_to_bv 64 C) (Z_to_bv 64 N) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
